Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
tipc: fix divide-by-zero in tipc_sk_filter_connect()

A user can set conn_timeout to any value via
setsockopt(TIPC_CONN_TIMEOUT), including values less than 4.  When a
SYN is rejected with TIPC_ERR_OVERLOAD and the retry path in
tipc_sk_filter_connect() executes:

    delay %= (tsk->conn_timeout / 4);

If conn_timeout is in the range [0, 3], the integer division yields 0,
and the modulo operation triggers a divide-by-zero exception, causing a
kernel oops/panic.

Fix this by clamping conn_timeout to a minimum of 4 at the point of use
in tipc_sk_filter_connect().

Oops: divide error: 0000 [#1] SMP KASAN NOPTI
CPU: 0 UID: 0 PID: 119 Comm: poc-F144 Not tainted 7.0.0-rc2+
RIP: 0010:tipc_sk_filter_rcv (net/tipc/socket.c:2236 net/tipc/socket.c:2362)
Call Trace:
 tipc_sk_backlog_rcv (include/linux/instrumented.h:82 include/linux/atomic/atomic-instrumented.h:32 include/net/sock.h:2357 net/tipc/socket.c:2406)
 __release_sock (include/net/sock.h:1185 net/core/sock.c:3213)
 release_sock (net/core/sock.c:3797)
 tipc_connect (net/tipc/socket.c:2570)
 __sys_connect (include/linux/file.h:62 include/linux/file.h:83 net/socket.c:2098)

Fixes: 6787927475e5 ("tipc: buffer overflow handling in listener socket")
Cc: stable@vger.kernel.org
Signed-off-by: Mehul Rao <mehulrao@gmail.com>
Reviewed-by: Tung Nguyen <tung.quang.nguyen@est.tech>
Link: https://patch.msgid.link/20260310170730.28841-1-mehulrao@gmail.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The `conn_timeout` socket option (TIPC_CONN_TIMEOUT) can be set by a user to a value less than 4 via `setsockopt()`. In `tipc_sk_filter_connect()`, during a retry path after a SYN rejection, the code executes `delay %= (tsk->conn_timeout / 4)`. When `conn_timeout` is in the range [0, 3], integer division yields 0, causing a divide-by-zero exception and kernel panic.

Here is the patch:
  */
 static bool tipc_sk_filter_connect(struct tipc_sock *tsk, struct sk_buff *skb,
 				   struct sk_buff_head *xmitq)
 {
 	struct sock *sk = &tsk->sk;
 	struct net *net = sock_net(sk);
 	struct tipc_msg *hdr = buf_msg(skb);
 	bool con_msg = msg_connected(hdr);
 	u32 pport = tsk_peer_port(tsk);
 	u32 pnode = tsk_peer_node(tsk);
 	u32 oport = msg_origport(hdr);
 	u32 onode = msg_orignode(hdr);
 	int err = msg_errcode(hdr);
 	unsigned long delay;

 	if (unlikely(msg_mcast(hdr)))
 		return false;
 	tsk->oneway = 0;

 	switch (sk->sk_state) {
 	case TIPC_CONNECTING:
 		/* Setup ACK */
 		if (likely(con_msg)) {
 			if (err)
 				break;
 			tipc_sk_finish_conn(tsk, oport, onode);
 			msg_set_importance(&tsk->phdr, msg_importance(hdr));
 			/* ACK+ message with data is added to receive queue */
 			if (msg_data_sz(hdr))
 				return true;
 			/* Empty ACK-, - wake up sleeping connect() and drop */
 			sk->sk_state_change(sk);
 			msg_set_dest_droppable(hdr, 1);
 			return false;
 		}
 		/* Ignore connectionless message if not from listening socket */
 		if (oport != pport || onode != pnode)
 			return false;

 		/* Rejected SYN */
 		if (err != TIPC_ERR_OVERLOAD)
 			break;

 		/* Prepare for new setup attempt if we have a SYN clone */
 		if (skb_queue_empty(&sk->sk_write_queue))
 			break;
 		get_random_bytes(&delay, 2);
+		if (tsk->conn_timeout < 4)
+			tsk->conn_timeout = 4;
 		delay %= (tsk->conn_timeout / 4);
 		delay = msecs_to_jiffies(delay + 100);
 		sk_reset_timer(sk, &sk->sk_timer, jiffies + delay);
 		return false;
 	case TIPC_OPEN:
 	case TIPC_DISCONNECTING:
 		return false;
 	case TIPC_LISTEN:
 		/* Accept only SYN message */
 		if (!msg_is_syn(hdr) &&
 		    tipc_node_get_capabilities(net, onode) & TIPC_SYN_BIT)
 			return false;
 		if (!con_msg && !err)
 			return true;
 		return false;
 	case TIPC_ESTABLISHED:
 		if (!skb_queue_empty(&sk->sk_write_queue))
 			tipc_sk_push_backlog(tsk, false);
 		/* Accept only connection-based messages sent by peer */
 		if (likely(con_msg && !err && pport == oport &&
 			   pnode == onode)) {
 			if (msg_ack_required(hdr)) {
 				struct sk_buff *skb;

 				skb = tipc_sk_build_ack(tsk);
 				if (skb) {
 					msg_set_nagle_ack(buf_msg(skb));
 					__skb_queue_tail(xmitq, skb);
 				}
 			}
 			return true;
 		}
 		if (!tsk_peer_msg(tsk, hdr))
 			return false;
 		if (!err)
 			return true;
 		tipc_set_sk_state(sk, TIPC_DISCONNECTING);
 		tipc_node_remove_conn(net, pnode, tsk->portid);
 		sk->sk_state_change(sk);
 		return true;
 	default:
 		pr_err("Unknown sk_state %u\n", sk->sk_state);
 	}
 	/* Abort connection setup attempt */
 	tipc_set_sk_state(sk, TIPC_DISCONNECTING);
 	sk->sk_err = ECONNREFUSED;
 	sk->sk_state_change(sk);
 	return true;
 }



